import { Document, Packer, Paragraph, TableOfContents, PageOrientation } from 'docx';

/**
 * Generate a DOCX containing a Word-native Table of Contents field.
 *
 * The TOC uses `\o "1-3"` (outline levels 1–3) which requires heading
 * styles to carry `outlineLvl`. After docx-merger renames styles, the
 * merged output needs post-processing to restore outline levels — see
 * `fixHeadingOutlineLevels()` in merge-docx.ts.
 *
 * No trailing page break — docx-merger inserts one between documents.
 */
export async function generateTocDocx(): Promise<Buffer> {
  const doc = new Document({
    features: { updateFields: true },
    sections: [
      {
        properties: {
          page: {
            size: {
              width: 11906, // A4
              height: 16838,
              orientation: PageOrientation.PORTRAIT,
            },
