export async function action({ request, context }: ActionFunctionArgs) {
  if (request.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 });
  }

  const session = context.get(sessionContext);
  const orgId = context.get(orgIdContext);

  if (!session?.user) {
    return jsonError('Unauthorized', 401);
  }

  const data = await request.json();
  const { project_id, format, page_size, generate_toc } = data;

  if (!project_id) {
    return jsonError('project_id is required', 400);
  }

  const project = await getProjectById(project_id, orgId);
  if (!project) {
    return jsonError('Project not found', 404);
  }

  const outline = await getBidOutlineByProjectId(project_id);
  if (!outline) {
    return jsonError('Outline not found', 404);
  }

  console.log('[finalize-bid] Outline found:', outline.id, 'Branch IDs:', outline.bid_branch_ids);

  let fileBuffer: Buffer;
  let fileName: string;
  let fileType: string;

  if (format === 'md') {
    // Markdown format
    const { mergedContent, sections } = await mergeSectionsByProjectId(project_id);
    if (!mergedContent || mergedContent.trim().length === 0) {
      return jsonError('No content to finalize. Please generate section content first.', 400);
    }

    let mdContent = `# ${project.name}\n\n`;
    if (generate_toc) {
      mdContent += '## 目录\n\n';
      for (const section of sections) {
        mdContent += `- [${section.title}](#${section.title})\n`;
      }
      mdContent += '\n---\n\n';
    }
    mdContent += mergedContent;

    fileBuffer = Buffer.from(mdContent, 'utf-8');
    fileName = `${project.name}_标书.md`;
    fileType = 'md';

    // Upload markdown to OSS
    const fileKey = `bid-doc/${orgId}/${project_id}/${crypto.randomBytes(8).toString('hex')}.md`;
    await storageClient.putObject(fileKey, fileBuffer, { 'content-type': 'text/markdown; charset=utf-8' });

    const bidDoc = await createBidDoc({
      org_id: orgId,
      creator_id: session.user.id,
      project_id,
      name: fileName,
      is_generated: true,
      file_name: fileName,
      file_key: fileKey,
      file_size: fileBuffer.length,
      file_type: fileType,
    });

    await updateProjectStatus(project_id, 'completed');
    return Response.json({ bidDocId: bidDoc.id });
  }

  // DOCX format — collect individual section DOCXes and merge
  const { buffers, sections } = await collectSectionDocxBuffers(project_id, orgId);

  if (buffers.length === 0) {
    return jsonError('No content to finalize. Please generate section content first.', 400);
  }

  // Prepend a TOC page if requested
  if (generate_toc) {
    const tocBuffer = await generateTocDocx();
    buffers.unshift(tocBuffer);
    console.log('[finalize-bid] Prepended TOC DOCX');
  }

  console.log('[finalize-bid] Merging', buffers.length, 'DOCX buffers');

  fileBuffer = await mergeDocxBuffers(buffers);
  fileName = `${project.name}_标书.docx`;
  fileType = 'docx';

  // Upload merged DOCX to OSS
  const fileKey = `bid-doc/${orgId}/${project_id}/${crypto.randomBytes(8).toString('hex')}.docx`;
  await storageClient.putObject(fileKey, fileBuffer, { 'content-type': DOCX_CONTENT_TYPE });

  const bidDoc = await createBidDoc({
    org_id: orgId,
    creator_id: session.user.id,
    project_id,
    name: fileName,
    is_generated: true,
    file_name: fileName,
    file_key: fileKey,
    file_size: fileBuffer.length,
    file_type: fileType,
  });

  await updateProjectStatus(project_id, 'completed');

  return Response.json({ bidDocId: bidDoc.id });
}

